head.script:
/*
    // 영문공시 오픈시 디자인소스에서 아래처럼 해야함.

	<mxcombo id="cmb_noti_obj_cd" class="mxcombo1" left="540" top="35" width="124" height="20">
	<property cbdata="9^전체,1^제출(국문)시스템,6^제출(영문)시스템,2^조회시스템,3^처리시스템" cbdatacolumns="value,text" index="0" inheritcolor="False" listcount="10" listexprformat="text^1^135" xpstyle="True"></property>
	<extproperty font-family="돋움" font-size="12"></extproperty>
	</mxcombo>

 */

scwin.contnId;
scwin.notiObjSysCode;

// 공지사항 입력_STF30400

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        $c.cm.PanelToGroupBox(panel_Top);
        edt_SDate.setValue($c.ut.calcMonth($c.ut.cGetToday2(), -1));
        edt_EDate.setValue($c.ut.cGetToday2());
        scwin.init();
        await scwin.listSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30400.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {void}
 * @hidden N
 */
scwin.init = function() {
    rdo_mkt_gubun.setValue(js_market);
    if (js_market === "9") {
        panel_mkt_gubun.show("");
    } else {
        panel_mkt_gubun.hide();
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name cmb_PeriodTp_onselchange
 * @description cmb_PeriodTp onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.cmb_PeriodTp_onselchange = function() {
    try {
        const vTp = $c.cp.valueOfIndex(cmb_PeriodTp, "VALUE", cmb_PeriodTp.getSelectedIndex());
        $c.stf.setFromToDate(vTp, edt_SDate, edt_EDate);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30400.cmb_PeriodTp_onselchange" });
    }
};

/**
 * @method
 * @name dts_noticeList_OnLoadCompleted
 * @description dts_noticeList 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_noticeList_OnLoadCompleted = function(rowcount) {
    try {
        $c.stf.fillGridHeaderTotalCnt(rowcount, panel_page);
        if (rowcount <= 0) {
            dts_noticeList.removeAll();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30400.dts_noticeList_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name MxGrid_2_OnDblClick
 * @description MxGrid_2 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.MxGrid_2_OnDblClick = async function(row, colid) {
    try {
        if (colid === 'TITLE') {
            scwin.setContnId(row);
            const options = {
                id: "ULDSTF30401",
                title: "공지사항 수정",
                type: "browserPopup",
                width: "930px",
                height: "520px",
                callbackFn: "scwin.popupCallback"
            };

            $c.win.openPopup("/dsclinfo/ULDSTF30401.gfm", options);
            await scwin.listSync();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30400.MxGrid_2_OnDblClick" });
    }
};

/**
 * @method
 * @name btn_Input_onclick
 * @description 「입력」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Input_onclick = async function() {
    try {
        scwin.contnId = "input";
        const options = {
            id: "ULDSTF30401",
            title: "공지사항 등록",
            type: "browserPopup",
            width: "930px",
            height: "520px",
            callbackFn: "scwin.popupCallback"
        };

        $c.win.openPopup("/dsclinfo/ULDSTF30401.gfm", options);
        await scwin.listSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30400.btn_Input_onclick" });
    }
};

/**
 * @method
 * @name bnt_Select_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.bnt_Select_onclick = async function() {
    try {
        await scwin.listSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30400.bnt_Select_onclick" });
    }
};

/**
 * @method
 * @name icn_SCal_onclick
 * @description icn_SCal 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.icn_SCal_onclick = function() {
    try {
        popUpCalendar2(edt_SDate);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30400.icn_SCal_onclick" });
    }
};

/**
 * @method
 * @name icn_ECal_onclick
 * @description icn_ECal 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.icn_ECal_onclick = function() {
    try {
        popUpCalendar2(edt_EDate);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30400.icn_ECal_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name listSync
 * @description list Sync 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listSync = async function() {
    if (await scwin.dateCheck() === false) {
        return;
    }
    const KeyWord = $c.cp.valueOfIndex(cmb_keyword, "VALUE", cmb_keyword.getSelectedIndex());
    const Condition1 = keyword.getValue();
    const SDate = edt_SDate.getValue();
    const EDate = edt_EDate.getValue();
    const UserId = usr_id.getValue();
    const NotiObjCode = $c.cp.valueOfIndex(cmb_noti_obj_cd, "VALUE", cmb_noti_obj_cd.getSelectedIndex());

    // 2009.09.01 채권공시 관련 추가
    if (js_bond_yn === "Y") {
        url = "/NoticeContent.do?method=listNoticeContent&KeyWord=" + KeyWord + "&Condition1=" + Condition1 + "&SDate=" + SDate + "&EDate=" + EDate + "&UserId=" + UserId + "&NotiObjCode=" + NotiObjCode + "&MKT_ID=4";
    } else {
    }
    url += "&SCREN_ID=" + "ULDSTF30400.xml";
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    const sbmOptions = {
        id : "sbm_dts_noticeList",
        action : "/NoticeContent.do",
        ref : "",
        target : "dts_noticeList=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    scwin.contnId = "";
};

/**
 * @method
 * @name popupCallback
 * @description browserPopup 팝업의 callback 함수. 부모창에서 팝업 결과 값을 처리한다.
 * @param {*} arg 팝업에서 전달받은 값
 * @returns {void}
 * @hidden N
 */
scwin.popupCallback = function (arg) {
    // TO-DO : arg 값 확인 후 업무 로직 추가
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name setContnId
 * @description set Contn Id 처리
 * @param {Object} obj 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.setContnId = function(obj) {
    if (scwin.contnId !== "input") {
        scwin.contnId = dts_noticeList.getCellData(Number(obj), "CONTN_ID");
    }
};

/**
 * @method
 * @name getContnId
 * @description get Contn Id 처리
 * @returns {void}
 * @hidden N
 */
scwin.getContnId = function() {
    return scwin.contnId;
};

/**
 * @method
 * @name setSysCode
 * @description set Sys Code 처리
 * @param {Object} obj 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.setSysCode = function(obj) {
    scwin.notiObjSysCode = dts_noticeList.getCellData(Number(obj), "NOTI_OBJ_SYS_TP_CD");
};

/**
 * @method
 * @name getSysCode
 * @description get Sys Code 처리
 * @returns {void}
 * @hidden N
 */
scwin.getSysCode = function() {
    return scwin.notiObjSysCode;
};

/**
 * @method
 * @name dateCheck
 * @description date Check 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dateCheck = async function() {
    if (parseInt(edt_SDate.getValue(), '10') > parseInt(edt_EDate.getValue(), '10')) {
        await $c.win.alert("[조회기간 시작일은 종료일보다 작아야 합니다.]다시 입력해주세요");
        edt_SDate.setValue($c.ut.cGetToday("yyyymmdd"));
        edt_EDate.setValue($c.ut.cGetToday("yyyymmdd"));
        return false;
    }
};
